contains

  pure subroutine ennuf_standardise_input(input_raw, domain, input_scaled)
    real(real64), intent(in) :: input_raw(ennuf_input_len)
    character(len=*), intent(in) :: domain
    real(real64), intent(out) :: input_scaled(ennuf_input_len)

    if (trim(domain) == "global") then
      input_scaled(1:53) = (input_raw(1:53) - theta_global_mean) / theta_global_std
      input_scaled(54:106) = (input_raw(54:106) - qt_global_mean) / qt_global_std
      input_scaled(107:159) = (input_raw(107:159) - u_global_mean) / u_global_std
      input_scaled(160:212) = (input_raw(160:212) - v_global_mean) / v_global_std
      input_scaled(213:265) = (input_raw(213:265) - pressure_global_mean) / pressure_global_std
      input_scaled(266) = (input_raw(266) - orog_global_mean) / orog_global_std
      input_scaled(267) = (input_raw(267) - hour_sin_global_mean) / hour_sin_global_std
      input_scaled(268) = (input_raw(268) - hour_cos_global_mean) / hour_cos_global_std
    else if (trim(domain) == "us2") then
      input_scaled(1:53) = (input_raw(1:53) - theta_us2_mean) / theta_us2_std
      input_scaled(54:106) = (input_raw(54:106) - qt_us2_mean) / qt_us2_std
      input_scaled(107:159) = (input_raw(107:159) - u_us2_mean) / u_us2_std
      input_scaled(160:212) = (input_raw(160:212) - v_us2_mean) / v_us2_std
      input_scaled(213:265) = (input_raw(213:265) - pressure_us2_mean) / pressure_us2_std
      input_scaled(266) = (input_raw(266) - orog_us2_mean) / orog_us2_std
      input_scaled(267) = (input_raw(267) - hour_sin_us2_mean) / hour_sin_us2_std
      input_scaled(268) = (input_raw(268) - hour_cos_us2_mean) / hour_cos_us2_std
    else
      input_scaled = input_raw
    end if
  end subroutine ennuf_standardise_input

end module gwd_ennuf_scaling_mod
